-- Sync local aria:qc-approval to the remote server's structure and add
-- the new QC Processed Locations table (M10.ReturnStockIn only).
--
-- Local's aria:qc-approval previously lacked the Return Stock Details /
-- Unloading Invoices ListView sections that already exist on the remote
-- server (192.187.121.34) -- this migration brings local's body in line
-- with remote's (both entities, ReturnStockOfficerItem and
-- DispatchInvoiceItem, are already registered locally -- see V302, V245),
-- plus inserts the new 'QC Processed Locations' RepeatingGroup section
-- (Batch No picker + Processed Area/Processed Type/Box Qty/PC Qty) right
-- after Return Stock Details, scoped by the same
-- visibleWhen == 'M10.ReturnStockIn' guard as its sibling sections.
--
-- No other flow variant (TankerInbound/TankerOutbound/PackUnload/etc.) is
-- affected -- every pre-existing section keeps its own visibleWhen intact.
UPDATE page_version pv
JOIN page_definition pd ON pd.current_version_id = pv.id
SET pv.body_json = '{"kind":"layout","schemaVersion":2,"slug":"aria:qc-approval","title":"QC Approval","status":"published","version":1,"roles":["QC","Manager","TenantAdmin"],"dataSources":[{"id":"q","kind":"rest","method":"GET","url":"/api/workflow/queue-for-page?pageCode=aria:qc-approval&size=200"}],"streams":[],"layout":[{"kind":"Grid","columns":12,"gap":16,"children":[{"kind":"Section","title":"QC Approval — Queue","span":12,"subtitle":"Vehicles awaiting a QC decision.","children":[{"kind":"WorkflowQueueList","persona":"QC","dataSource":"q","pageSize":25,"cardFields":[],"fillFormOnSelect":true,"priorityShading":true,"fillLookupEntity":"GatePass","fillLookupField":"gp_number","secondLineFields":[{"field":"gpNumber","label":""},{"field":"flowVariantCode","label":""},{"field":"queueReason","label":"Reason"}],"filterFields":[{"field":"vehicleNo","label":"Vehicle No"},{"field":"gpNumber","label":"GP Number"},{"field":"flowVariantCode","label":"Flow Variant"}],"priorityOverrideField":"priority_override","resolveCodeFields":[{"field":"oil_rm_item","entity":"SkuMaster","codeField":"sku_code","nameField":"sku_name","delimiter":", "}],"cardImageLookup":{"sourceField":"vehicle_category","entity":"VehicleCategory","codeField":"code","imageField":"image_url","targetField":"vehicle_category_image_url"},"backgroundImageField":"vehicle_category_image_url"}]},{"kind":"Section","title":"Sample Identification","span":12,"children":[{"kind":"Form","bindings":{"fields":[{"name":"gp_number","label":"Gate Pass # (scan / pick / type)","type":"select","required":true,"scannable":true,"freeSolo":true,"optionsSource":{"type":"url","url":"workflow/queue-for-page?pageCode=aria:qc-approval&size=200","valueField":"gpNumber","labelField":"gpNumber","entity":"GatePass","entityLookupField":"gp_number"},"onChangeFill":{"item_category":"item_category","flow_variant_code":"flow_variant_code","instanceId":"workflow_instance_id","oil_rm_item":"oil_rm_item","vehicle_no":"vehicle_no"},"priorityOverrideField":"priority_override"},{"name":"vehicle_no","label":"Vehicle Number","type":"text","readOnly":true},{"name":"sample_jar_id","label":"Sample / Sample Lot ID","type":"text","placeholder":"SAMPLE-2026-0617","visibleWhen":"#form.flow_variant_code != ''M10.ReturnStockIn''","requiredWhen":"#form.flow_variant_code != ''M10.ReturnStockIn''"},{"name":"qc_officer_id","label":"QC Officer Name","required":true,"type":"select","optionsSource":{"type":"datasource","spec":{"type":"entity","entity":"Employee","select":["id","employeename"],"filter":{"field":"status","op":"eq","value":"A"},"sort":[{"field":"employeename","dir":"asc"}]},"valueField":"id","labelField":"employeename"}},{"name":"queue_reason","label":"Reason for Skipping Priority Sample","type":"select","options":[{"label":"Sample Not Ready for Higher-Priority Item","value":"SAMPLE_NOT_READY"},{"label":"QC Officer Occupied with Another Sample","value":"QC_OFFICER_BUSY"},{"label":"Urgent Dispatch Required","value":"URGENT_DISPATCH_REQUIRED"},{"label":"Documents Pending for Priority Vehicle","value":"DOCUMENTS_PENDING"},{"label":"Others","value":"OTHERS"}],"visibleWhen":"#form.priority_override == true && #form.flow_variant_code != ''M10.ReturnStockIn''","requiredWhen":"#form.priority_override == true && #form.flow_variant_code != ''M10.ReturnStockIn''"},{"name":"queue_reason_other","label":"Please specify the reason","type":"text","visibleWhen":"#form.priority_override == true && #form.queue_reason == ''OTHERS'' && #form.flow_variant_code != ''M10.ReturnStockIn''","requiredWhen":"#form.priority_override == true && #form.queue_reason == ''OTHERS'' && #form.flow_variant_code != ''M10.ReturnStockIn''"},{"name":"flow_variant_code","label":"Flow Variant","type":"text","readOnly":true},{"name":"priority_override","label":"","type":"text","readOnly":true}]}}]},{"kind":"Section","title":"Return Stock Details","span":12,"subtitle":"Batch/SKU/Qty captured by the Return Stock Officer. Add the QC Batch No. and Stock-wise Unloading Area for each line before submitting.","visibleWhen":"#form.flow_variant_code == ''M10.ReturnStockIn''","children":[{"kind":"ListView","name":"returnStockItems","dataSource":{"type":"entity","entity":"ReturnStockOfficerItem","filter":{"field":"workflow_instance_id","op":"eq","value":"{{form.instanceId}}"},"autoLoad":false,"refreshOn":["form.instanceId.change"]},"columns":[{"field":"batch_no","label":"Batch No","editable":false},{"field":"qc_batch_no","label":"QC Batch No","widget_kind":"text","editable":true},{"field":"sku_name","label":"SKU Name","editable":false},{"field":"qty","label":"Qty","render":"number","editable":false},{"field":"good_stock_qty","label":"Good Stock","render":"number","editable":false},{"field":"expiry_stock_qty","label":"Expiry Stock","render":"number","editable":false},{"field":"unloading_area","label":"Stock-wise Unloading Area","widget_kind":"select","editable":true,"required":true,"options":[{"label":"G1 — Main Stores","value":"G1"},{"label":"G2 — Packing Material Stores","value":"G2"},{"label":"G3 — Returns / Quarantine","value":"G3"},{"label":"G4 — FG Stores","value":"G4"}]}],"pageSize":50,"hideToolbar":true,"hideSearch":true,"hideActionsColumn":true,"localEditOnly":true,"disableRowClick":true}]},{"kind":"Section","title":"QC Processed Locations","span":12,"subtitle":"Allocate each Return Stock batch''s Box/PC across one or more processed areas.","visibleWhen":"#form.flow_variant_code == ''M10.ReturnStockIn''","children":[{"kind":"RepeatingGroup","name":"qcProcessedLocations","label":"Processed Locations","minRows":1,"defaultRows":1,"columns":[{"name":"return_stock_officer_item_id","label":"Batch No","type":"select","required":true,"width":"1.4fr","optionsSource":{"type":"datasource","valueField":"id","labelField":["batch_no","sku_name"],"labelJoin":" — ","spec":{"type":"entity","entity":"ReturnStockOfficerItem","select":["id","batch_no","sku_name"],"filter":{"field":"workflow_instance_id","op":"eq","value":"page:instanceId"},"sort":[{"field":"batch_no","dir":"asc"}]}}},{"name":"processed_area","label":"Processed Area","type":"text","required":true,"width":"1fr"},{"name":"processed_type","label":"Processed Type","type":"select","required":true,"width":"1fr","options":["Repack","Cutting"]},{"name":"box_qty","label":"Box Qty","type":"number","required":true,"width":"0.7fr"},{"name":"pc_qty","label":"PC Qty","type":"number","required":true,"width":"0.7fr"}],"rowActions":[{"kind":"Button","label":"🗑️ Delete","action":"repeatingGroup.deleteRow","color":"error","confirmBeforeAction":true}],"footerActions":[{"kind":"Button","label":"+ Add","action":"repeatingGroup.addRow","color":"secondary"}]}]},{"kind":"Section","title":"Unloading Invoices","span":12,"subtitle":"Invoice line items captured at dispatch for this vehicle. Pick a tank location for every item before submitting.","visibleWhen":"#form.flow_variant_code == ''M10.TankerInbound''","children":[{"kind":"ListView","name":"unloadingInvoices","dataSource":{"type":"entity","entity":"DispatchInvoiceItem","filter":{"field":"workflow_instance_id","op":"eq","value":"{{form.instanceId}}"},"autoLoad":false,"refreshOn":["form.instanceId.change"]},"columns":[{"field":"invoice_no","label":"Invoice No","editable":false},{"field":"order_id","label":"Order Id","editable":false},{"field":"vendor_name","label":"Vendor","editable":false},{"field":"rd_code","label":"RD Code","editable":false},{"field":"sku_code","label":"SKU","editable":false},{"field":"sku_name","label":"SKU Name","editable":false},{"field":"qty","label":"Qty","render":"number","editable":false},{"field":"tank_location","label":"Tank Location","widget_kind":"select","editable":true,"required":true,"optionsSource":{"type":"datasource","valueField":"code","labelField":"code","spec":{"type":"entity","entity":"TankerLocation","select":["code","label"],"filter":{"field":"active","op":"eq","value":1},"sort":[{"field":"code","dir":"asc"}]}}}],"pageSize":50,"hideToolbar":true,"hideSearch":true,"hideActionsColumn":true,"localEditOnly":true,"disableRowClick":true}]},{"kind":"Section","title":"Oil Parameters (only if item category = RM Oil / FG)","span":12,"subtitle":"Skip this section if the receipt is packing material / return / non-oil.","children":[{"kind":"Form","bindings":{"fields":[{"name":"density_kgl","label":"Density (kg/L) — spec 0.910–0.930 for groundnut","type":"number","visibleWhen":"#form.item_category == ''RM_OIL'' || #form.item_category == ''FG''","requiredWhen":"#form.item_category == ''RM_OIL'' || #form.item_category == ''FG''"},{"name":"ffa_pct","label":"Free Fatty Acid (%) — spec ≤ 0.20","type":"number","visibleWhen":"#form.item_category == ''RM_OIL'' || #form.item_category == ''FG''","requiredWhen":"#form.item_category == ''RM_OIL'' || #form.item_category == ''FG''"},{"name":"colour_rating","label":"Colour vs reference","type":"select","options":[{"label":"Golden / Pale yellow — Pass","value":"PASS_GOLDEN"},{"label":"Light orange — Pass","value":"PASS_ORANGE"},{"label":"Dark brown — Fail","value":"FAIL_DARK"},{"label":"Cloudy — Fail","value":"FAIL_CLOUDY"}],"visibleWhen":"#form.item_category == ''RM_OIL'' || #form.item_category == ''FG''","requiredWhen":"#form.item_category == ''RM_OIL'' || #form.item_category == ''FG''"},{"name":"temperature_c","label":"Temperature (°C) — spec ≤ 35","type":"number","visibleWhen":"#form.item_category == ''RM_OIL'' || #form.item_category == ''FG''","requiredWhen":"#form.item_category == ''RM_OIL'' || #form.item_category == ''FG''"}]}}],"visibleWhen":"false"},{"kind":"Section","title":"Photo + Seal","span":12,"children":[{"kind":"Form","bindings":{"fields":[{"name":"sample_photo","label":"Sample Photo","type":"file","accept":"image/*"},{"name":"seal_unlock_no","label":"Seal Unlock #","type":"text"},{"name":"oil_sample_recovered","label":"Oil Sample Recovered (after seal lock)","type":"select","options":["YES","NO"],"visibleWhen":"#form.flow_variant_code == ''M10.TankerInbound''","requiredWhen":"#form.flow_variant_code == ''M10.TankerInbound''"},{"name":"unloading_supervisor_name","label":"Unloading Supervisor Name","type":"select","visibleWhen":"#form.flow_variant_code == ''M10.TankerInbound''","requiredWhen":"#form.flow_variant_code == ''M10.TankerInbound''","optionsSource":{"type":"datasource","spec":{"type":"entity","entity":"Employee","select":["id","employeename"],"filter":{"and":[{"field":"employeetype","op":"eq","value":"Supervisor"},{"field":"status","op":"eq","value":"A"}]},"sort":[{"field":"employeename","dir":"asc"}]},"valueField":"id","labelField":"employeename"}},{"name":"unloading_location","label":"Unloading Material / FG Stock Location","type":"select","options":[{"label":"G1 — Main Stores","value":"G1"},{"label":"G2 — Packing Material Stores","value":"G2"},{"label":"G3 — Returns / Quarantine","value":"G3"},{"label":"G4 — FG Stores","value":"G4"}],"visibleWhen":"#form.item_category == ''RETURN'' || #form.flow_variant_code == ''M10.PackUnload'' || #form.flow_variant_code == ''M10.FGUnloading''","requiredWhen":"#form.item_category == ''RETURN'' || #form.flow_variant_code == ''M10.PackUnload'' || #form.flow_variant_code == ''M10.FGUnloading''"},{"name":"qc_notes","label":"Notes","type":"textarea","rows":3}]}}]},{"kind":"Section","title":"Decision","span":12,"children":[{"kind":"Form","bindings":{"fields":[{"name":"status","label":"QC Decision","type":"select","required":true,"options":[{"label":"✓ APPROVED — all parameters pass","value":"APPROVED"},{"label":"✗ REJECTED — see notes / debit vendor","value":"REJECTED"}]},{"name":"qc_reject_reason","label":"Rejection Reason","type":"textarea","rows":3,"visibleWhen":"#form.status == ''REJECTED''","requiredWhen":"#form.status == ''REJECTED''"}]}},{"kind":"WorkflowActionButton","action":"workflow.transition","label":"Submit QC Decision","variant":"primary","args":{"includeListData":["unloadingInvoices","returnStockItems"]}}]}]}]}'
WHERE pd.code = 'aria:qc-approval' AND pv.status = 'PUBLISHED';
